{
	int							ply = sys->pause_player;
	stringx						name;

	assert(sys->pause_player != -1);

	SoundScriptManager::inst()->unpause();
	sys->navigationEvent=  SoundScriptManager::inst()->playEvent(SoundScriptManager::SS_FE_ONX);
