	case Follow:
		if (ply == 0) name = "FOLLOW_CLOSE_CAM0";
		else name = "FOLLOW_CLOSE_CAM1";	
		break;
	case Beach:
		if (ply == 0) name = "BEACH_CAM0";
		else name = "BEACH_CAM1";	
		break;
	case FPS:
		if (ply == 0) name = "FPS_CAM0";
